from pathlib import Path
import base64, hashlib, zlib

path = Path("frontend/ancient-cities/rome-410-476/js/app.js")
old = path.read_bytes()
expected = "5b069855b5943abc6e062d74e3d0b8bb685b7d37e8da68c67e77f9db44ff8ced"
if hashlib.sha256(old).hexdigest() != expected:
    raise SystemExit("Rome app.js no longer matches the reviewed Phase-1 source; refusing to replace it.")

payload = ""
new = zlib.decompress(base64.b64decode(payload))
expected_new = "30728b07ca5d96851127ed0416053a705e43a4abb178938656fb018e05abb574"
if hashlib.sha256(new).hexdigest() != expected_new:
    raise SystemExit("Embedded Phase-2 payload checksum failed.")
path.write_bytes(new)
print(f"Replaced {path}: {len(old)} -> {len(new)} bytes")
